mapper.select:
SELECT * FROM ( SELECT
WHERE ast05_rcv_pay_cd LIKE #{c.payCode} AND COALESCE(a.ast01_asset_type, '1') LIKE #{c.assetType} AND ( ( '1' = #{c.abroType} AND COALESCE(ast06_cur_cd, 'KRW') = 'KRW' ) OR ( '2' = #{c.abroType} AND COALESCE(ast06_cur_cd, 'KRW') != 'KRW' ) )
AND ast05_tr_code_id = #{c.trCodeId}
AND ast06_corp_id = #{c.corpId}
AND ast06_ast_class_tree_id = #{c.astClassTreeId}
AND ast06_date BETWEEN #{c.startDate} AND #{c.closeDate} AND ast06_tr_cd IN ( SELECT ast15_tr_cd FROM ast15_tr_code_window WHERE ast15_company_id = ast06_company_id AND ast15_window_class_nm = #{c.windowClassName} ) AND ast06_company_id = #{c.companyId} AND ( ( #{c.userId} IN ( SELECT ast06_person_id UNION ALL SELECT ast10_person_id FROM ast10_manager WHERE ast10_manager_type = '1' AND ast10_link_id IN (ast06_tr_id, ast06_ast_class_tree_id) ) ) OR ( #{c.orgId} IN ( SELECT ast10_org_id FROM ast10_manager WHERE ast10_manager_type = '2' AND ast10_link_id IN (ast06_tr_id, ast06_ast_class_tree_id) UNION ALL SELECT CAST(f_get_empTrans(ast06_person_id, to_date(substr(ast06_tr_id || '', 1, 8), 'yyyymmdd'), 'org_code_id') AS NUMERIC) ) ) ) ) t WHERE UPPER(COALESCE(tr_name, '') || COALESCE(corp_account_name, '') || COALESCE(ast_class_name, '') || COALESCE(class_tree_name, '') || COALESCE(note, '')) LIKE '%' || UPPER(#{c.searchText}) || '%'
AND COALESCE(book_io_type, '9') IN ('1','9')
ORDER BY date, tr_id

